};

String resolveFoodImageUrl({String? slug, String? name, String? category}) {
  if (slug != null && slug.isNotEmpty) {
    final exact = foodImageMap[slug];
    if (exact != null && exact.isNotEmpty) return exact;
    for (final entry in foodImageMap.entries) {
      if (slug.contains(entry.key) || entry.key.contains(slug)) {
        return entry.value;
      }
    }
  }
  if (category != null && category.isNotEmpty) {
    final catMatch = foodCategoryFallbackMap[category.toUpperCase()];
    if (catMatch != null && catMatch.isNotEmpty) return catMatch;
  }
  return 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=500&auto=format&fit=crop&q=80';
}
